=== FILE: rr_arbiter_props.sv ===
// Formal wrapper and properties for rr_arbiter, written from interface_spec.md.
// Immediate assertions only (open Yosys front end). No assumptions on inputs.
module rr_arbiter_fv (
    input wire       clk,
    input wire       rst_n,
    input wire [2:0] req
);
    wire [2:0] grant;
    wire [1:0] last;

    rr_arbiter dut (
        .clk  (clk),
        .rst_n(rst_n),
        .req  (req),
        .grant(grant),
        .last (last)
    );

    // ------------------------------------------------------------------
    // Bookkeeping
    // ------------------------------------------------------------------
    reg f_past_valid = 1'b0;
    reg f_rst_done   = 1'b0;   // a reset edge has been seen
    always @(posedge clk) begin
        f_past_valid <= 1'b1;
        if (!rst_n)
            f_rst_done <= 1'b1;
    end

    // Expected grant from the spec's rotation: last+1, last+2, last (mod 3).
    wire [1:0] f_p0 = (last == 2'd2) ? 2'd0 : (last + 2'd1);
    wire [1:0] f_p1 = (f_p0 == 2'd2) ? 2'd0 : (f_p0 + 2'd1);
    wire [1:0] f_p2 = last;
    wire [2:0] f_exp = req[f_p0] ? (3'b001 << f_p0) :
                       req[f_p1] ? (3'b001 << f_p1) :
                       req[f_p2] ? (3'b001 << f_p2) : 3'b000;

    // Wait counters for RR-BOUND: edges at which requester i asked and was
    // refused, consecutively, since the last reset, drop or grant.
    reg [1:0] f_w0 = 2'd0;
    reg [1:0] f_w1 = 2'd0;
    reg [1:0] f_w2 = 2'd0;
    always @(posedge clk) begin
        if (!rst_n || !req[0] || grant[0]) f_w0 <= 2'd0;
        else if (f_w0 != 2'd3)             f_w0 <= f_w0 + 2'd1;
        if (!rst_n || !req[1] || grant[1]) f_w1 <= 2'd0;
        else if (f_w1 != 2'd3)             f_w1 <= f_w1 + 2'd1;
        if (!rst_n || !req[2] || grant[2]) f_w2 <= 2'd0;
        else if (f_w2 != 2'd3)             f_w2 <= f_w2 + 2'd1;
    end

    // ------------------------------------------------------------------
    // Combinational properties
    // ------------------------------------------------------------------
    always @(*) begin
        // grant: at most one bit high (port table)
        assert((grant & (grant - 3'b001)) == 3'b000);
        // [req:RR-ONLY-REQUESTERS]
        assert((grant & ~req) == 3'b000);

        if (f_rst_done) begin
            // helper: last is 0, 1 or 2 once reset has been applied
            assert(last != 2'd3);
            assert(f_past_valid);
            // [req:RR-PICK] (also implies a grant whenever req != 0)
            assert(grant == f_exp);
            // helpers for induction: wait never exceeds two refusals
            assert(f_w0 <= 2'd2);
            assert(f_w1 <= 2'd2);
            assert(f_w2 <= 2'd2);
        end

        // [req:RR-IDLE]
        if (f_rst_done && req == 3'b000)
            assert(grant == 3'b000);

        // [req:RR-BOUND]: after two refusals, the third edge grants
        if (f_rst_done && f_w0 == 2'd2 && req[0])
            assert(grant[0]);
        if (f_rst_done && f_w1 == 2'd2 && req[1])
            assert(grant[1]);
        if (f_rst_done && f_w2 == 2'd2 && req[2])
            assert(grant[2]);
    end

    // ------------------------------------------------------------------
    // Clocked properties
    // ------------------------------------------------------------------
    always @(posedge clk) begin
        // [req:RR-RESET]
        if (f_past_valid && !$past(rst_n))
            assert(last == 2'd2);

        // [req:RR-ROTATE]
        if (f_past_valid && $past(rst_n) && $past(grant) != 3'b000)
            assert(($past(grant[0]) && last == 2'd0) ||
                   ($past(grant[1]) && last == 2'd1) ||
                   ($past(grant[2]) && last == 2'd2));

        // [req:RR-HOLD]
        if (f_past_valid && $past(rst_n) && $past(grant) == 3'b000)
            assert(last == $past(last));

        // [req:RR-YIELD]
        if (f_past_valid && $past(rst_n) && $past(grant) != 3'b000
            && (req & ~$past(grant)) != 3'b000)
            assert((grant & $past(grant)) == 3'b000);
    end

    // ------------------------------------------------------------------
    // Covers: scenarios the proof must still allow
    // ------------------------------------------------------------------
    always @(posedge clk) begin
        if (f_past_valid)
            cover(!$past(rst_n));
        if (f_rst_done) begin
            cover(grant == 3'b001);
            cover(grant == 3'b010);
            cover(grant == 3'b100);
            cover(req == 3'b000);
            cover(req == 3'b111 && grant == 3'b100);
            cover(f_w0 == 2'd2 && req[0]);
            cover(f_w1 == 2'd2 && req[1]);
            cover(f_w2 == 2'd2 && req[2]);
        end
        if (f_past_valid && f_rst_done && $past(rst_n) && $past(grant) != 3'b000
            && (req & ~$past(grant)) != 3'b000)
            cover(grant != 3'b000);
        if (f_past_valid && f_rst_done && $past(rst_n) && $past(grant) == 3'b000)
            cover(req != 3'b000);
    end
endmodule
